下面的数组队列在反复入队出队后会错误地报告「队列已满」。指出缺陷并给出最小修改。

```c
#define CAP 8
int data[CAP];
int front = 0, rear = 0;

void enqueue(int x) {
    if (rear == CAP) { puts("FULL"); return; }
    data[rear++] = x;
}
int dequeue(int *out) {
    if (front == rear) return 0;
    *out = data[front++];
    return 1;
}
```

answer.reference_code:
#define CAP 8
int data[CAP];
int front = 0, rear = 0, size = 0;

int is_full(void)  { return size == CAP; }
int is_empty(void) { return size == 0; }

void enqueue(int x) {
    if (is_full()) { puts("FULL"); return; }
    data[rear] = x;
    rear = (rear + 1) % CAP;   /* 环形推进 */
    size++;
}
int dequeue(int *out) {
    if (is_empty()) return 0;
    *out = data[front];
    front = (front + 1) % CAP; /* 环形推进 */
    size--;
    return 1;
}

