下面代码用单调栈求每个元素的「下一个更大元素」。给定 `a = {2, 1, 5, 3, 4}`，程序输出的五行 `-> n` 依次是什么？

```c
int a[] = {2, 1, 5, 3, 4};
int n = 5, stk[5], top = 0, nge[5];
for (int i = 0; i < n; i++) nge[i] = -1;
for (int i = 0; i < n; i++) {
    while (top > 0 && a[stk[top-1]] < a[i]) nge[stk[--top]] = a[i];
    stk[top++] = i;
}
for (int i = 0; i < n; i++) printf("a[%d]=%d -> %d\n", i, a[i], nge[i]);
```

answer.reference_code:
int isValid(const char *s) {
    char st[10000]; int top = 0;
    for (int i = 0; s[i]; i++) {
        char c = s[i];
        if (c=='('||c=='['||c=='{') st[top++] = c;
        else {
            if (top == 0) return 0;
            char o = st[--top];
            if ((c==')'&&o!='(')||(c==']'&&o!='[')||(c=='}'&&o!='{')) return 0;
        }
    }
    return top == 0;
}

int* dailyTemperatures(int* t, int n, int* returnSize) {
    int *res = calloc(n, sizeof(int));
    int *stk = malloc(n * sizeof(int));
    int top = 0;
    for (int i = 0; i < n; i++) {
        while (top > 0 && t[stk[top-1]] < t[i]) {
            int j = stk[--top];
            res[j] = i - j;          /* 天数差 */
        }
        stk[top++] = i;
    }
    free(stk);
    *returnSize = n;
    return res;
}

int* maxSlidingWindow(int* a, int n, int k, int* returnSize) {
    int *res = malloc((n - k + 1) * sizeof(int));
    int *q = malloc(n * sizeof(int));
    int head = 0, tail = 0, m = 0;
    for (int i = 0; i < n; i++) {
        while (tail > head && a[q[tail-1]] <= a[i]) tail--;  /* 队尾淘汰更小者 */
        q[tail++] = i;
        if (q[head] <= i - k) head++;                        /* 队首过期 */
        if (i >= k - 1) res[m++] = a[q[head]];
    }
    free(q);
    *returnSize = m;
    return res;
}
